// Track Vimeo Video Play
function waitForElement(selector, callback) {
    var interval = setInterval(function () {
        var element = document.querySelector(selector);
        if (element) {
            clearInterval(interval);
            callback(element);
        }
    }, 100);
    // Clear interval after 10 seconds if the element is not found
    setTimeout(function () {
        clearInterval(interval);
    }, 15000);
}
// Function to dynamically load the Vimeo Player API if it's not already present
function loadVimeoPlayerApi(callback) {
    if (typeof Vimeo !== 'undefined') {
        callback();
    } else {
        var script = document.createElement('script');
        script.src = 'https://player.vimeo.com/api/player.js';
        script.onload = function () {
            callback();
        };
        document.head.appendChild(script);
    }
}
// Function to setup play event tracking for the specific Vimeo video
function setupVimeoVideoTracking() {
    // Target the specific iframe by its source URL or any other distinguishing attribute
    var iframe = document.querySelector(
        'iframe[title="WinkBeds 120-Night Risk-Free Trial"]',
    );
    if (iframe) {
        trackVimeoVideoPlayEvent(iframe);
    }
}
// Function to track the play event for the Vimeo video
function trackVimeoVideoPlayEvent(iframe) {
    loadVimeoPlayerApi(function () {
        window.player = new Vimeo.Player(iframe);
        player.on('play', function () {
            // Place your event tracking code here. Example:
            window._conv_q = window._conv_q || [];
            window._conv_q.push(['triggerConversion', '100326996']);
        });
    });
}
waitForElement(
    'iframe[title="WinkBeds 120-Night Risk-Free Trial"]',
    setupVimeoVideoTracking,
);

