(function () {
    try {
        /* main variables */
        var debug = 1;
        var variation_name = "winkBedsTest114CustomActivation";

        function waitForElement(selector, trigger) {
            var interval = setInterval(function () {
                if (
                    document &&
                    document.querySelector(selector) &&
                    document.querySelectorAll(selector).length > 0
                ) {
                    clearInterval(interval);
                    trigger();
                }
            }, 50);
            setTimeout(function () {
                clearInterval(interval);
            }, 15000);
        }

        // WIN114 - Scroll to any review (goal code)
        function fireGoalCode() {
            window._conv_q = window._conv_q || [];
            _conv_q.push(["triggerConversion", "100329757"]);
        }

        function activateExperiment() {
            window.test_114_Experiment = 1;
            window._conv_q = window._conv_q || [];
            //    window._conv_q.push(['executeExperiment', '100344679']);
            window._conv_q.push(['executeExperiment', '100344982']);
            console.log("test 114 activate")
        }

        function init() {
            // Create an IntersectionObserver instance
            var observer = new IntersectionObserver((entries, observer) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        if (!window.experiment114AlreadyActivated) {
                            window.experiment114AlreadyActivated = true;
                            activateExperiment()
                            fireGoalCode()
                        }

                        // You can stop observing once the element is detected
                        observer.disconnect();
                    }
                });
            }, {
                threshold: 0.1 // Trigger when 10% of the element is visible
            });

            var reviewSection = document.querySelector("#shopify-section-testimonials");
            if (reviewSection) {
                if (!window.observerAddedT114) {
                    window.observerAddedT114 = true;
                    observer.observe(reviewSection);
                }
            }
        }

        // Start observing the target element
        if (window.location.href.includes('https://www.winkbeds.com') && window.location.pathname == "/pages/shop-winkbed") {
            waitForElement("#shopify-section-testimonials", init)
        }

    } catch (e) {
        if (debug) console.log(e, "error in Test" + variation_name);
    }
})();

