// WIN 158
(function () {
    try {
        const debug = 1;
        const variation_name = "cre-t-win158";

        // Respect timed popup logic
        const hasSeenTimedModal = sessionStorage.getItem("hasSeenTimedModal") === "true";
        const exitPopupTriggered = sessionStorage.getItem("exit_popup_shown") === "true";

        // Don't trigger exit intent if timed popup already shown or exit popup already triggered
        if (hasSeenTimedModal || exitPopupTriggered) {
            if (debug) console.log("Skipping exit intent: hasSeenTimedModal OR already shown");
            return;
        }

        const options = {
            isActive: false,
        };

        function createExitIntent(userOptions = {}) {
            const DEFAULT_CONFIG = {
                scrollSensitivity: 0.3,
                scrollVelocityThreshold: 1.5,
                veolocityFeature: true,
                inactivityTimeout: 15000,
                fireOnce: true,
                callback: () => { },
                conditions: {
                    mouseLeave: window.innerWidth >= 768,
                    scrollUp: window.innerWidth < 768,
                    inactivity: false,
                },
            };

            const VALIDATION_RULES = {
                scrollSensitivity: {
                    min: 0.1,
                    max: 1.0
                },
                scrollVelocityThreshold: {
                    min: 0.1,
                    max: 10.0
                },
                inactivityTimeout: {
                    min: 1000,
                    max: 300000
                },
            };

            const config = {
                ...DEFAULT_CONFIG,
                ...userOptions,
                conditions: {
                    ...DEFAULT_CONFIG.conditions,
                    ...(userOptions.conditions || {}),
                },
            };

            Object.entries(VALIDATION_RULES).forEach(([key, {
                min,
                max
            }]) => {
                const value = config[key];
                if (value < min || value > max) {
                    throw new Error(`${key} must be between ${min} and ${max}.`);
                }
            });

            if (typeof config.callback !== 'function') {
                throw new Error('Callback must be a function.');
            }

            let state = {
                isTriggered: false,
                lastScrollTop: window.scrollY || document.documentElement.scrollTop,
                lastScrollTime: Date.now(),
                inactivityTimer: null,
            };

            const throttle = (func, wait) => {
                let inThrottle;
                return function (...args) {
                    if (!inThrottle) {
                        func.apply(this, args);
                        inThrottle = true;
                        setTimeout(() => (inThrottle = false), wait);
                    }
                };
            };

            const debounce = (func, wait) => {
                let timeout;
                return function (...args) {
                    clearTimeout(timeout);
                    timeout = setTimeout(() => func.apply(this, args), wait);
                };
            };

            const triggerExitIntent = (triggerType) => {
                if (config.fireOnce && state.isTriggered) return;

                state.isTriggered = true;
                config.callback();
                sessionStorage.setItem("exit_popup_shown", "true");
                //   sessionStorage.setItem("hasSeenTimedModal", "true"); // prevent timed popup later
                if (debug) console.log(`Exit Intent Triggered: ${triggerType}`);
                if (config.fireOnce) destroy();
            };

            const handleMouseLeave = (event) => {
                if (event.clientY <= 50) {
                    triggerExitIntent('Mouse Leave');
                }
            };

            const handleScroll = () => {
                const currentScrollTop = window.scrollY || document.documentElement.scrollTop;
                const now = Date.now();

                if (currentScrollTop >= state.lastScrollTop) {
                    state.lastScrollTop = currentScrollTop;
                    state.lastScrollTime = now;
                    return;
                }

                const scrollDistance = state.lastScrollTop - currentScrollTop;
                const timeDiff = now - state.lastScrollTime;
                const distanceThreshold = document.documentElement.clientHeight * config.scrollSensitivity;

                if (scrollDistance >= distanceThreshold) {
                    if (config.veolocityFeature) {
                        const velocity = timeDiff > 0 ? scrollDistance / timeDiff : 0;
                        if (velocity >= config.scrollVelocityThreshold) {
                            triggerExitIntent(`Rapid Scroll Up (${velocity.toFixed(2)} px/ms)`);
                        }
                    } else {
                        triggerExitIntent('Scroll Up threshold');
                    }
                }

                state.lastScrollTop = currentScrollTop;
                state.lastScrollTime = now;
            };

            const throttledScrollHandler = throttle(handleScroll, 200);
            const debouncedMouseLeaveHandler = debounce(handleMouseLeave, 200);
            const activeListeners = [];

            const addListener = (el, evt, fn, opts) => {
                el.addEventListener(evt, fn, opts);
                activeListeners.push([el, evt, fn, opts]);
            };

            const attachEventListeners = () => {
                if (config.conditions.mouseLeave)
                    addListener(document, 'mousemove', debouncedMouseLeaveHandler);
                if (config.conditions.scrollUp)
                    addListener(window, 'scroll', throttledScrollHandler, {
                        passive: true
                    });
            };

            const destroy = () => {
                activeListeners.forEach(([el, evt, fn, opts]) => {
                    el.removeEventListener(evt, fn, opts);
                });
                if (debug) console.log("ExitIntent listeners removed");
            };

            attachEventListeners();
        }

        function activate() {
            if (!window.experiment158AlreadyActivated) {
                window.experiment158AlreadyActivated = true;
                window.test_158_Experiment = 1;
                window._conv_q = window._conv_q || [];
                window._conv_q.push(["executeExperiment", "100347363"]);
            }
        }
        // Define your callback activation function
        function activateTest() {
            options.isActive = true;
            activate();
        }

        function initTest() {
            if (options.isActive) return;
            createExitIntent({
                callback: function () {
                    activateTest();
                }
            });
        }

        initTest();
    } catch (e) {
        console.warn(e, "error in Test exitIntentPopup");
    }
})();

