// 257 ACTIVATION
(function () {
    try {
        /* main variables */
        var debug = 1;
        var variation_name = "creT257Activation";
        let options = {
            isActive: false, // Initial state
        };

        function getCookie(name) {
            const value = `; ${document.cookie}`;
            const parts = value.split(`; ${name}=`);
            if (parts.length === 2) return parts.pop().split(';').shift();
        }

        // set cookie for session
        function setSessionCookie(name, value) {
            document.cookie = `${name}=${value}; path=/;`;
        }

        function cameFromCheckout() {
            return getCookie('cre_257_checkout_visited') === 'true';
        }

        // Signal B: Shopify's own localStorage marker that a checkout session exists
        function hasCheckoutSessionIdentifier() {
            try {
                const ui = JSON.parse(localStorage.getItem('__ui') || '{}');
                return !!(ui && ui[2] && ui[2][0] && ui[2][0].checkoutSessionIdentifier);
            } catch (e) {
                if (debug) console.log(e, 'error parsing __ui in ' + variation_name);
                return false;
            }
        }

        function hasVisitedCheckoutAndReturned() {
            return cameFromCheckout() && hasCheckoutSessionIdentifier();
        }

        // ---- Conditions 3 & 4: exactly one WinkBed in cart, without Frost Cooling Cover ----
        async function cartMeetsMattressCondition() {
            try {
                const cart = await fetch('/cart.js').then(res => res.json());

                if (!cart || !cart.items || !cart.items.length) return false;

                const winkbedItems = cart.items.filter(item =>
                    item.title.toLowerCase().includes('winkbed')
                );

                // must be exactly one WinkBed mattress in cart
                if (winkbedItems.length !== 1) return false;

                const item = winkbedItems[0];

                if (item.quantity !== 1) return false; // must be exactly one WinkBed mattress in cart

                // must NOT already have Frost Cooling Cover
                const hasFrostCooling = /frost\s*cooling\s*cover/i.test(item.variant_title);
                return !hasFrostCooling;
            } catch (e) {
                if (debug) console.log(e, 'error checking cart in ' + variation_name);
                return false;
            }
        }

        // ---- Activation ----
        function activate() {
            options.isActive = true;
            if (!window.experiment257AlreadyActivated) {
                window.experiment257AlreadyActivated = true;
                window.test_257_Experiment = 1;
                window._conv_q = window._conv_q || [];
                window._conv_q.push(["executeExperiment", "100350512"]);
                console.log("Test " + variation_name + " Activated");
            }
        }

        // ---- Master check: all 4 conditions must pass, run once ----
        async function checkAllConditionsAndActivate() {

            if (!hasVisitedCheckoutAndReturned()) return;

            const cartOk = await cartMeetsMattressCondition();
            if (!cartOk) return;

            activate();
        }


        function init() {

            setTimeout(checkAllConditionsAndActivate, 3000);

            if (!window.testcreT257_event) {
                window.testcreT257_event = true;
                window.addEventListener('pageshow', function (event) {
                    // event.persisted is true if the page was restored from the Back-Forward Cache
                    if (event.persisted) {

                        waitForElement('.pop-cart__close', function () {
                            document.querySelector('.pop-cart__close').click();
                        });

                        setTimeout(checkAllConditionsAndActivate, 3000);
                    }
                });
            }
        }


        waitForElement('body', init, 25, 10000);

    } catch (e) {
        if (debug) console.log(e, "error in Test" + variation_name);
    }

})();


