(function () {
  try {
    /* main variables */
    var debug = 0;
    var variation_name = "cre-t-268-custom-trigger";

    /* all Pure helper functions */

    function live(selector, event, callback, context) {
      if (typeof callback !== "function") return;
      context = context || document;

      context.addEventListener(event, function (e) {
        var el = e.target.closest(selector);
        if (el && context.contains(el)) {
          callback.call(el, e);
        }
      });
    }

    function waitForElement(selector, trigger, delayInterval = 50, delayTimeout = 15000) {
      var interval = setInterval(function () {
        if (document && document.querySelector(selector) && document.querySelectorAll(selector).length > 0) {
          clearInterval(interval);
          trigger();
        }
      }, delayInterval);

      setTimeout(function () {
        clearInterval(interval);
      }, delayTimeout);
    }

    /* Trigger functions */

    /* activates the experiment once, on the first qualifying engagement */
    function activateExperiment() {
      if (!window.experiment268AlreadyActivated) {
        window.experiment268AlreadyActivated = true;
        window.test_268_Experiment = 1;
        window._conv_q = window._conv_q || [];
        window._conv_q.push(["executeExperiment", "100350606"]);
        console.log("Test creT268 Activated");
      }
    }

    /* the lightbox and zoom entry points, which do not change the carousel slide */
    function bindLightboxEngagement() {
      live(".cre-t-264-grid-item", "click", activateExperiment);
      live(".img-zoom.prod-detail__imgs__zoom", "click", activateExperiment);
    }

    /* any movement of the main carousel: swipe, arrows, thumbs or the 264 scroller */
    function bindCarouselEngagement() {
      var gallery = document.querySelector(".prod-images .gallery-top");
      if (!gallery) return;
      if (!gallery.swiper) return;

      gallery.swiper.on("sliderMove", activateExperiment);
      gallery.swiper.on("slideChange", activateExperiment);
    }

    /* Trigger Init */
    function init() {
      if (window.cre_t_268_trigger_bound) return;
      window.cre_t_268_trigger_bound = true;

      bindLightboxEngagement();
       waitForElement(".prod-images .gallery-top.swiper-container-initialized", bindCarouselEngagement, 50, 15000);
    }

    /* Initialise trigger */
    waitForElement("#gallery-top-images .swiper-slide", init, 50, 15000);
  } catch (e) {
    if (debug) console.log(e, "error in Test " + variation_name);
  }
})();


