            var mattressSize = document.getElementById("size-select").value;
              var mattressPrice = productPrice[mattressSize];

              var newCurrent = mattressPrice,newWas = mattressPrice;

              var originalCurrent =parseFloat(document.querySelector(".price-row__pay-option-price").innerText.replace(/[^0-9.-]+/g, ''));
              newCurrent += originalCurrent;

              var originalWas = parseFloat(document.querySelector(".strike.price-row__strike-price:not(#test-cloned-strike)").innerText.replace(/[^0-9.-]+/g, ''));
              newWas += originalWas;
