    function observeTextChange(targetElement, callback) {
      if (!targetElement) {
        console.error("No target element provided");
        return;
      }

      // Create a MutationObserver instance
      const observer = new MutationObserver((mutationsList) => {
        for (const mutation of mutationsList) {
          if (mutation.type === "childList" || mutation.type === "characterData") {
            callback(targetElement.textContent);
          }
        }
      });

      // Observer configuration
      const config = {
        characterData: true, // detects changes in text nodes
        childList: false,
        subtree: true,
      };

      // Start observing the target element
      observer.observe(targetElement, config);

      // Return observer in case you want to disconnect later
      return observer;
    }

    function oldPrice() {
      // Get the strike price element
      var priceElement = document.querySelector(".order-form-price-row .price-row__strike-price");
      var priceText = priceElement ? priceElement.innerText : "";

      // Extract price, keeping the commas and formatting with $
      var extractedPrice = "$" + priceText.replace(/[^0-9,]/g, ""); // Allow commas and numbers

      // Get the pay option price element
      var payOptionElement = document.querySelector(".order-form-price-row .price-row__pay-option-price");
      var payOptionText = payOptionElement ? payOptionElement.innerText : "";

      // Extract pay option price, keeping the commas and formatting with $
      var extractedPayOptionPrice = "$" + payOptionText.replace(/[^0-9,]/g, ""); // Allow commas and numbers

      // Return an object containing both prices
      return {
        extractedPrice: extractedPrice,
        extractedPayOptionPrice: extractedPayOptionPrice,
      };
    }

