(function () {
  try { 
    var debug = 0;
    var variation_name = "cre-t-248";

    function waitForElement(selector, trigger, delayInterval = 50, delayTimeout = 15000) {
      var interval = setInterval(function () {
        if (document && document.querySelector(selector) && document.querySelectorAll(selector).length > 0) {
          clearInterval(interval);
          trigger();
        }
      }, delayInterval);
      setTimeout(function () {
        clearInterval(interval);
      }, delayTimeout);
    }

    function debounce(func, delay = 100) {
      if (typeof func !== "function") return function () {};
      var timeout;
      return function () {
        var context = this;
        var args = arguments;
        clearTimeout(timeout);
        timeout = setTimeout(function () {
          func.apply(context, args);
        }, delay);
      };
    }

    function live(selector, event, callback, context) {
      if (typeof callback !== "function") return;
      context = context || document;
      context.addEventListener(event, function (e) {
        var el = e.target.closest(selector);
        if (el && context.contains(el)) {
          callback.call(el, e);
        }
      });
    }

    var sectionHTML = `<section id="cre-t-248-section" class="cre-t-248-section">
  <div class="cre-t-248-inner">
    <h1 class="generic-page__title">Try the WinkBed in person</h1>
    <div class="generic-page__content subtitle">
      <p>Visit a nearby showroom to test comfort and firmness before you decide. Or order online with a 120-night trial.</p>
    </div>
    <div id="stockist-widget" data-stockist-widget-tag="u22544"></div>
  </div>
</section>`;

    function loadStockistScript() {
      if (document.querySelector('script[src*="stockist.co/embed"]')) return;
      var script = document.createElement('script');
      script.src = 'https://stockist.co/embed/v1/widget.min.js';
      script.charset = 'utf-8';
      script.async = true;
      document.body.appendChild(script);
    }

    var userExpandedShowMore = false;

    function isMobile() {
      return window.innerWidth <= 767;
    }

    function resetShowMore(ul) {
      var existingBtn = document.querySelector('.cre-t-248-show-btn');
      if (existingBtn) existingBtn.remove();
      ul.querySelectorAll('.cre-t-248-hidden').forEach(function (el) {
        el.classList.remove('cre-t-248-hidden');
      });
    }

    function applyShowMore(ul, resultList) {
      if (!isMobile()) return;

      var items = ul.querySelectorAll('li.stockist-list-result');
      if (items.length <= 3) return;

      for (var i = 3; i < items.length; i++) {
        items[i].classList.add('cre-t-248-hidden');
      }

      // Insert after resultList (outside the observed subtree) to avoid re-triggering the MutationObserver
      resultList.insertAdjacentHTML('afterend', '<div class="cre-t-248-show-btn"><span class="cre-t-248-show-more">Show More</span></div>');
    }

    function observeResultList() {
      var resultList = document.querySelector('#cre-t-248-section .stockist-result-list');
      if (!resultList) return;

      var lastItemCount = -1;

      var observer = new MutationObserver(debounce(function () {
        var ul = resultList.querySelector('ul');
        if (!ul) {
          var existingBtn = document.querySelector('.cre-t-248-show-btn');
          if (existingBtn) existingBtn.remove();
          lastItemCount = 0;
          userExpandedShowMore = false;
          return;
        }
        var currentCount = ul.querySelectorAll('li.stockist-list-result').length;
        if (currentCount === lastItemCount) return;
        // count dropped to 0 means a new search started — reset expanded state
        if (currentCount === 0) userExpandedShowMore = false;
        lastItemCount = currentCount;
        if (userExpandedShowMore) return;
        observer.disconnect();
        resetShowMore(ul);
        applyShowMore(ul, resultList);
        observer.observe(resultList, { childList: true, subtree: true });
      }, 300));

      observer.observe(resultList, { childList: true, subtree: true });
    }

    function setupEvents() {
      live('.cre-t-248-show-btn', 'click', function () {
        var wrapper = this;
        var span = wrapper.querySelector('.cre-t-248-show-more');
        var resultList = document.querySelector('#cre-t-248-section .stockist-result-list');
        if (!resultList) return;
        var ul = resultList.querySelector('ul');
        if (!ul) return;

        if (span.textContent === 'Show More') {
          userExpandedShowMore = true;
          ul.querySelectorAll('.cre-t-248-hidden').forEach(function (el) {
            el.classList.remove('cre-t-248-hidden');
          });
          span.textContent = 'Show Less';
          wrapper.classList.add('expanded');
        } else {
          userExpandedShowMore = false;
          var allItems = ul.querySelectorAll('li.stockist-list-result');
          for (var i = 3; i < allItems.length; i++) {
            allItems[i].classList.add('cre-t-248-hidden');
          }
          span.textContent = 'Show More';
          wrapper.classList.remove('expanded');
          var section = document.querySelector('#cre-t-248-section');
          if (section) section.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      });

      live('#cre-t-248-section [class="stockist-map stockist-map-leaflet"]', 'mousedown', function () {
          window._conv_q = window._conv_q || [];  
          _conv_q.push(["triggerConversion", "100334072"]);
      });

      live('#cre-t-248-section .stockist-result.stockist-list-result', 'click', function () {
            window._conv_q = window._conv_q || [];  
          _conv_q.push(["triggerConversion", "100334072"]);
      });

      window.addEventListener('resize', debounce(function () {
        if (userExpandedShowMore) return;
        var resultList = document.querySelector('#cre-t-248-section .stockist-result-list');
        if (!resultList) return;
        var ul = resultList.querySelector('ul');
        if (!ul) return;
        resetShowMore(ul);
        applyShowMore(ul, resultList);
      }, 200));
    }

    function init() {
      if (document.querySelector('#cre-t-248-section')) return;

      var anchor = document.querySelector('#shopify-section-shop-the-winkbed-warranty.shopify-section');
      if (!anchor) return;

      anchor.insertAdjacentHTML('beforebegin', sectionHTML);
      loadStockistScript();
      if (!window.creT248EventsBound) {
        window.creT248EventsBound = true;
        setupEvents();
      }
      waitForElement('#cre-t-248-section .stockist-result-list', observeResultList, 100, 30000);
    }

    waitForElement('#shopify-section-shop-the-winkbed-warranty.shopify-section', init, 50, 15000);
  } catch (e) {
    if (debug) console.log(e, 'error in Test ' + variation_name);
  }
})();
