(function () {
  try {
    /* main variables */
    var debug = 1;
    var variation_name = "cre-t-275-control";
    var TARGET_SELECTOR = 'li[data-accessory-name*="Add the Adjustable WinkBase"] h4';

    /* Helper: Wait for element */
    function waitForElement(selector, trigger, delayInterval, delayTimeout) {
      delayInterval = delayInterval || 50;
      delayTimeout = delayTimeout || 15000;

      var interval = setInterval(function () {
        if (document && document.querySelector(selector)) {
          clearInterval(interval);
          trigger();
        }
      }, delayInterval);

      setTimeout(function () {
        clearInterval(interval);
      }, delayTimeout);
    }

    /* Helper: Live event listener */
    function live(selector, event, callback, context) {
      if (typeof callback !== "function") return;
      context = context || document;

      context.addEventListener(event, function (e) {
        var el = e.target.closest(selector);
        if (el && context.contains(el)) {
          callback.call(el, e);
        }
      });
    }

    /* Helper: Parse name and current price from data-accessory-name attribute */
    function parseAccessoryName(rawName) {
      var parsedMatch = rawName.match(/^(Add (?:an|the)\s+)(.+?)\s*-\s*\$([\d,]+)\s*$/i);
      if (!parsedMatch) return null;

      return {
        prefix: parsedMatch[1],
        name: parsedMatch[2],
        currentPrice: "$" + parsedMatch[3],
      };
    }

    /* If a fake clone from an earlier run is present, remove it */
    function removeExistingFake(realElement) {
      var next = realElement.nextElementSibling;
      if (next && next.classList && next.classList.contains("cre-t-275-fake-title")) {
        next.remove();
      }
    }

    /* Reads data attribute and applies the modified title + fake price */
    function applyAdjustableWinkBaseTitle() {
      var realTitleElement = document.querySelector(TARGET_SELECTOR);
      if (!realTitleElement) return;

      var trayItem = realTitleElement.closest("[data-accessory-name]");
      if (!trayItem) return;

      var rawName = trayItem.getAttribute("data-accessory-name") || "";
      var parsedAccessory = parseAccessoryName(rawName);
      if (!parsedAccessory) return;

      // Remove previous fake element if exists
      removeExistingFake(realTitleElement);

      // Remove "Adjustable " from display name if present
      var displayName = parsedAccessory.name.replace(/Adjustable\s*/gi, "");

      // Hide original element
      realTitleElement.classList.add("cre-t-275-original-hidden");

      // Insert fake title right after the original element
      var fakeHtml = `<h4 class="accessory-item-title cre-t-275-fake-title"><span>${parsedAccessory.prefix}</span>${displayName} - ${parsedAccessory.currentPrice}</h4>`;
      realTitleElement.insertAdjacentHTML("afterend", fakeHtml);

      if (debug) console.log("[cre-t-275] Specific element title applied:", parsedAccessory.currentPrice);
    }

    /* Wait for site to finish updating DOM after dropdown change */
    function refreshTitle() {
      waitForElement(TARGET_SELECTOR, function () {
        // Checking data attribute readiness
        var interval = setInterval(function () {
          var realTitleElement = document.querySelector(TARGET_SELECTOR);
          if (realTitleElement) {
            var trayItem = realTitleElement.closest("[data-accessory-name]");
            if (trayItem && trayItem.getAttribute("data-accessory-name")) {
              applyAdjustableWinkBaseTitle();
            }
          }
        }, 100);

        setTimeout(function () {
          clearInterval(interval);
        }, 3000);
      });
    }

    /* Bind change events on size and firmness dropdowns */
    function bindDropdownEvents() {
      if (window.cre_275_adjustable_title_events_bound) return;
      window.cre_275_adjustable_title_events_bound = true;

      live("#size-select", "change", function () {
        setTimeout(refreshTitle, 300);
      });

      live("#firmness-select", "change", function () {
        setTimeout(refreshTitle, 300);
      });
    }

    /* Init Variation */
    function init() {
      document.body.classList.add(variation_name);
      refreshTitle();
      bindDropdownEvents();
    }

    /* Start when order form loaded */
    waitForElement("#orderForm.loaded", init, 50, 15000);
  } catch (e) {
    if (debug) console.log(e, "error in Test " + variation_name);
  }
})();
