(function () {
  try {
    /* main variables */
    var debug = 0;
    var variation_name = "cre-t-268";

    /* quote images to move to the last positions, in this order */
    /* the People image only exists in the lightbox, added by test 264 */
    var quoteImageFiles = ["WC-2025-PDP.png", "Nap-lab-25.png", "Strat-25-PDP.png", "cre-170-people-large"];

    /* all Pure helper functions */

    function waitForElement(selector, trigger, delayInterval = 50, delayTimeout = 15000) {
      var interval = setInterval(function () {
        if (document && document.querySelector(selector) && document.querySelectorAll(selector).length > 0) {
          clearInterval(interval);
          trigger();
        }
      }, delayInterval);

      setTimeout(function () {
        clearInterval(interval);
      }, delayTimeout);
    }

    /* Variation functions */

    /* reads the image source of a slide, whether the slide is an img or wraps one */
    function getSlideImageSource(slide) {
      if (slide.tagName === "IMG") {
        return slide.getAttribute("src");
      }

      var innerImage = slide.querySelector("img");
      if (innerImage) {
        return innerImage.getAttribute("src");
      }

      return "";
    }

    /* finds the slide in one slider wrapper that uses the given image file */
    function findSlideByImageFile(wrapper, fileName) {
      var slides = wrapper.children;
      var index;
      var imageSource;

      for (index = 0; index < slides.length; index++) {
        imageSource = getSlideImageSource(slides[index]);
        if (imageSource && imageSource.indexOf(fileName) > -1) {
          return slides[index];
        }
      }

      return null;
    }

    /* moves every listed quote slide to the end of one slider wrapper */
    function moveQuoteSlidesToEnd(wrapper) {
      if (!wrapper) return;
      if (wrapper.getAttribute("data-cre-t-268-quotes-moved") === "1") return;

      quoteImageFiles.forEach(function (fileName) {
        var quoteSlide = findSlideByImageFile(wrapper, fileName);
        if (quoteSlide) {
          wrapper.appendChild(quoteSlide);
        }
      });

      wrapper.setAttribute("data-cre-t-268-quotes-moved", "1");
    }

    /* tells Swiper to re-read the reordered slides */
    function refreshSwiperInstance(container) {
      if (!container) return;
      if (!container.swiper) return;

      container.swiper.update();
    }

    /* the slide element a slider is currently resting on, before any reorder */
    function getActiveSlide(container) {
      if (!container) return null;
      if (!container.swiper) return null;

      var swiperInstance = container.swiper;
      var activeSlide = swiperInstance.slides[swiperInstance.activeIndex];
      if (!activeSlide) return null;

      return activeSlide;
    }

    /* puts a slider back on the slide it was resting on, at its new position */
    function restoreActiveSlide(container, activeSlide) {
      if (!container) return;
      if (!container.swiper) return;
      if (!activeSlide) return;

      var swiperInstance = container.swiper;
      var slides = swiperInstance.slides;
      var newIndex = -1;
      var index;

      for (index = 0; index < slides.length; index++) {
        if (slides[index] === activeSlide) {
          newIndex = index;
          break;
        }
      }

      if (newIndex === -1) return;
      if (newIndex === swiperInstance.activeIndex) return;

      swiperInstance.slideTo(newIndex, 0);
    }

    /* reorders one slider, leaving the user on the same slide position */
    function reorderSlider(wrapperSelector, containerSelector) {
      var wrapper = document.querySelector(wrapperSelector);
      if (!wrapper) return;

      moveQuoteSlidesToEnd(wrapper);
      refreshSwiperInstance(document.querySelector(containerSelector));
    }

    /* the carousel is browsed by position, so the user stays on the slide number they moved to */
    function moveMainCarouselQuoteSlides() {
      reorderSlider("#gallery-top-images", ".prod-images .gallery-top");
    }

    function moveThumbnailQuoteSlides() {
      reorderSlider("#gallery-thumbs-images", ".prod-images .gallery-thumbs");
    }

    /* the lightbox is opened on a chosen image, so it follows that image to its new position */
    function moveLightboxQuoteSlides() {
      var wrapper = document.querySelector("#lightbox-slider-wrapper");
      if (!wrapper) return;

      var container = document.querySelector(".lightbox-slider");
      var activeSlide = getActiveSlide(container);

      moveQuoteSlidesToEnd(wrapper);
      refreshSwiperInstance(container);
      restoreActiveSlide(container, activeSlide);
    }

    /* Variation Init */
    function init() {
      if (document.body.classList.contains(variation_name)) return;
      document.body.classList.add(variation_name);

      moveMainCarouselQuoteSlides();
      waitForElement("#gallery-thumbs-images", moveThumbnailQuoteSlides, 50, 15000);
      waitForElement("#lightbox-slider-wrapper", moveLightboxQuoteSlides, 50, 15000);
    }

    /* Initialise variation */
    waitForElement("#gallery-top-images .swiper-slide", init, 50, 15000);
  } catch (e) {
    if (debug) console.log(e, "error in Test " + variation_name);
  }
})();
